constexpr double twoPi = 6.283185307179586;
struct Rng { juce::uint32 s; float next() { s = s * 1664525u + 1013904223u; return (float) ((s >> 8) & 0xffffff) / 8388608.0f - 1.0f; } };

juce::AudioBuffer<float> mono (double rate, double secs) { juce::AudioBuffer<float> b (1, (int) (rate * secs)); b.clear(); return b; }

void normalise (juce::AudioBuffer<float>& b, float peak = 0.7f)
{
    const float m = b.getMagnitude (0, b.getNumSamples());
    if (m > 0) b.applyGain (peak / m);
}

juce::AudioBuffer<float> kick (double sr, float f0, float decay)
{
    auto b = mono (sr, 0.6); auto* d = b.getWritePointer (0);
    double ph = 0;
    for (int i = 0; i < b.getNumSamples(); ++i)
    {
        const double t = i / sr;
        const double f = f0 + 140.0 * std::exp (-t * 30.0);
        ph += twoPi * f / sr;
        d[i] = (float) (std::sin (ph) * std::exp (-t * decay) + 0.3 * std::exp (-t * 400.0) * std::sin (ph * 3));
    }
    normalise (b); return b;
}
juce::AudioBuffer<float> snare (double sr, float tone, juce::uint32 seed)
{
    auto b = mono (sr, 0.4); auto* d = b.getWritePointer (0); Rng r { seed };
    float lp = 0;
    for (int i = 0; i < b.getNumSamples(); ++i)
    {
        const double t = i / sr;
        const float n = r.next(); lp += 0.5f * (n - lp);
        d[i] = (float) ((n - lp) * std::exp (-t * 18.0) * 0.8 + std::sin (twoPi * tone * t) * std::exp (-t * 30.0) * 0.6);
    }
    normalise (b); return b;
}
juce::AudioBuffer<float> hat (double sr, float decay, juce::uint32 seed)
{
    auto b = mono (sr, 0.25); auto* d = b.getWritePointer (0); Rng r { seed };
    float x1 = 0, y1 = 0;
    for (int i = 0; i < b.getNumSamples(); ++i)
    {
        const double t = i / sr;
        const float n = r.next();
        const float hp = 0.9f * (y1 + n - x1); x1 = n; y1 = hp;   // one-pole high pass
        d[i] = (float) (hp * std::exp (-t * decay));
    }
    normalise (b, 0.5f); return b;
}
juce::AudioBuffer<float> clap (double sr, juce::uint32 seed)
{
    auto b = mono (sr, 0.4); auto* d = b.getWritePointer (0); Rng r { seed };
    for (int i = 0; i < b.getNumSamples(); ++i)
    {
        const double t = i / sr;
        double env = 0;
        for (int k = 0; k < 4; ++k) { const double tk = t - k * 0.011; if (tk >= 0) env += std::exp (-tk * (k == 3 ? 14.0 : 120.0)); }
        d[i] = (float) (r.next() * env);
    }
    normalise (b); return b;
}
juce::AudioBuffer<float> tom (double sr, float f0) { auto b = kick (sr, f0, 9.0f); return b; }

juce::AudioBuffer<float> tone (double sr, double secs, std::initializer_list<double> freqs, double bright, double decay, bool pluck)
{
    auto b = mono (sr, secs); auto* d = b.getWritePointer (0);
    for (int i = 0; i < b.getNumSamples(); ++i)
    {
        const double t = i / sr;
        double v = 0;
        for (double f : freqs)
            for (int h = 1; h <= 12; ++h)
            {
                if (f * h > sr * 0.45) break;
                const double inharm = pluck ? (1.0 + 0.0004 * h * h) : 1.0;
                v += std::sin (twoPi * f * h * inharm * t) * std::pow (bright, h - 1) / h * std::exp (-t * decay * (pluck ? h * 0.6 : 1.0));
            }
        const double att = juce::jmin (1.0, t / (pluck ? 0.003 : 0.04));
        d[i] = (float) (v * att);
    }
    normalise (b); return b;
}

// formant (vowel) synthesis: a glottal-like pulse through three resonators
struct Formant { double f, bw, g; };
const Formant kVowels[5][3] = {
    { { 800, 80, 1.0 }, { 1150, 90, 0.5 }, { 2900, 120, 0.25 } },   // ah
    { { 270, 60, 1.0 }, { 2290, 100, 0.4 }, { 3010, 120, 0.3 } },   // ee
    { { 450, 70, 1.0 }, { 800, 80, 0.6 }, { 2830, 100, 0.2 } },     // oh
    { { 325, 60, 1.0 }, { 700, 70, 0.4 }, { 2530, 100, 0.15 } },    // oo
    { { 400, 60, 1.0 }, { 1700, 90, 0.5 }, { 2600, 110, 0.3 } },    // eh
};
struct Reson
{
    double a1 = 0, a2 = 0, g = 0, y1 = 0, y2 = 0;
    void set (double f, double bw, double gain, double sr) { const double r = std::exp (-M_PI * bw / sr); a1 = 2 * r * std::cos (twoPi * f / sr); a2 = -r * r; g = gain * (1 - r); }
    double run (double x) { const double y = g * x + a1 * y1 + a2 * y2; y2 = y1; y1 = y; return y; }
};

juce::AudioBuffer<float> vowels (double sr, double secs, const std::vector<std::pair<int, double>>& notes, juce::uint32 seed)
{
    auto b = mono (sr, secs); auto* d = b.getWritePointer (0); Rng r { seed };
    Reson rs[3];
    double ph = 0;
    const int n = b.getNumSamples();
    const double noteLen = secs / (double) notes.size();
    for (int i = 0; i < n; ++i)
    {
        const double t = i / sr;
        const int k = juce::jmin ((int) notes.size() - 1, (int) (t / noteLen));
        const double local = t - k * noteLen;
        const int v0 = notes[(size_t) k].first, v1 = notes[(size_t) juce::jmin ((int) notes.size() - 1, k + 1)].first;
        const double morph = juce::jlimit (0.0, 1.0, (local - noteLen * 0.7) / (noteLen * 0.3));
        if (i % 32 == 0)
            for (int f = 0; f < 3; ++f)
            {
                const auto& A = kVowels[v0][f]; const auto& B = kVowels[v1][f];
                rs[f].set (A.f + (B.f - A.f) * morph, A.bw + (B.bw - A.bw) * morph, A.g + (B.g - A.g) * morph, sr);
            }
        const double vib = 1.0 + 0.012 * std::sin (twoPi * 5.2 * t);
        const double f0 = notes[(size_t) k].second * vib;
        ph += f0 / sr;
        if (ph >= 1) ph -= 1;
        const double pulse = (ph < 0.4 ? std::sin (M_PI * ph / 0.4) : 0.0) + 0.03 * r.next();
        double y = 0;
        for (auto& rr : rs) y += rr.run (pulse);
        const double env = juce::jmin (1.0, local / 0.05) * juce::jmin (1.0, (noteLen - local) / 0.06 + 0.2);
        d[i] = (float) (y * env);
    }
    normalise (b); return b;
}
