juce::StringArray kitNames() { return { "drums", "tones", "noise", "vowels" }; }
juce::String kitLabel (const juce::String& w)
{
    if (w == "drums") return "SYNTH DRUMS";
    if (w == "tones") return "TONES & BELLS";
    if (w == "noise") return "NOISE & AIR";
    return "SUNG VOWELS";
}

std::vector<Sound> kit (const juce::String& which, double sr)
{
    std::vector<Sound> out;
    if (which == "drums")
    {
        out.push_back ({ "kick low", kick (sr, 48, 7) });
        out.push_back ({ "kick punch", kick (sr, 62, 12) });
        out.push_back ({ "snare", snare (sr, 190, 11) });
        out.push_back ({ "snare tight", snare (sr, 240, 23) });
        out.push_back ({ "hat closed", hat (sr, 60, 5) });
        out.push_back ({ "hat open", hat (sr, 9, 7) });
        out.push_back ({ "clap", clap (sr, 3) });
        out.push_back ({ "tom high", tom (sr, 180) });
        out.push_back ({ "tom low", tom (sr, 110) });
    }
    else if (which == "tones")
    {
        out.push_back ({ "bell", tone (sr, 2.5, { 523.25, 1318.5 }, 0.5, 1.6, true) });
        out.push_back ({ "pluck A", tone (sr, 1.2, { 220 }, 0.7, 3.0, true) });
        out.push_back ({ "pluck E", tone (sr, 1.2, { 329.63 }, 0.7, 3.0, true) });
        out.push_back ({ "pad minor", tone (sr, 3.0, { 220, 261.63, 329.63 }, 0.35, 0.3, false) });
        out.push_back ({ "pad major", tone (sr, 3.0, { 196, 246.94, 293.66 }, 0.35, 0.3, false) });
        out.push_back ({ "bass", tone (sr, 1.5, { 55 }, 0.8, 1.2, false) });
        out.push_back ({ "organ", tone (sr, 2.0, { 392, 784 }, 0.2, 0.2, false) });
    }
    else if (which == "noise")
    {
        Rng r { 77 };
        for (int k = 0; k < 4; ++k)
        {
            auto b = mono (sr, 2.0); auto* d = b.getWritePointer (0);
            float lp = 0;
            for (int i = 0; i < b.getNumSamples(); ++i)
            {
                const double t = i / sr;
                const float c = (float) (0.02 + 0.6 * (0.5 + 0.5 * std::sin (twoPi * (0.25 + k * 0.2) * t)));
                lp += c * (r.next() - lp);
                d[i] = lp * (float) std::sin (M_PI * t / 2.0);
            }
            normalise (b, 0.6f);
            out.push_back ({ juce::String ("air ") + juce::String (k + 1), std::move (b) });
        }
    }
    else
    {
        out.push_back ({ "ah", vowels (sr, 1.5, { { 0, 196 } }, 1) });
        out.push_back ({ "ee", vowels (sr, 1.5, { { 1, 220 } }, 2) });
        out.push_back ({ "oh", vowels (sr, 1.5, { { 2, 174.6 } }, 3) });
        out.push_back ({ "oo", vowels (sr, 1.5, { { 3, 246.9 } }, 4) });
        out.push_back ({ "eh", vowels (sr, 1.5, { { 4, 261.6 } }, 5) });
    }
    return out;
}

juce::AudioBuffer<float> beatLoop (double sr, int bars, double bpm)
{
    const double beat = 60.0 / bpm;
    const double secs = bars * 4 * beat;
    juce::AudioBuffer<float> out (2, (int) (secs * sr)); out.clear();
    auto k = kick (sr, 52, 8), s = snare (sr, 200, 9), h = hat (sr, 55, 4), ho = hat (sr, 10, 6);
    auto put = [&] (const juce::AudioBuffer<float>& src, double at, float g, float pan)
    {
        const int o = (int) (at * sr);
        const int n = juce::jmin (src.getNumSamples(), out.getNumSamples() - o);
        if (n <= 0) return;
        out.addFrom (0, o, src, 0, 0, n, g * (1.0f - pan));
        out.addFrom (1, o, src, 0, 0, n, g * (1.0f + pan));
    };
    for (int bar = 0; bar < bars; ++bar)
    {
        const double b0 = bar * 4 * beat;
        put (k, b0, 0.9f, 0); put (k, b0 + 2.5 * beat, 0.7f, 0); put (k, b0 + 1.75 * beat, 0.5f, 0);
        put (s, b0 + beat, 0.7f, 0.1f); put (s, b0 + 3 * beat, 0.7f, 0.1f);
        for (int e = 0; e < 8; ++e) put (e == 7 ? ho : h, b0 + e * 0.5 * beat, e % 2 ? 0.25f : 0.35f, -0.3f);
    }
    normalise (out, 0.8f);
    return out;
}

juce::AudioBuffer<float> vowelPhrase (double sr, double secs)
{
    auto m = vowels (sr, secs, { { 0, 220 }, { 1, 246.9 }, { 2, 261.6 }, { 0, 293.7 }, { 3, 261.6 }, { 4, 220 }, { 2, 196 }, { 0, 220 } }, 9);
    juce::AudioBuffer<float> out (2, m.getNumSamples());
    out.copyFrom (0, 0, m, 0, 0, m.getNumSamples()); out.copyFrom (1, 0, m, 0, 0, m.getNumSamples());
    return out;
}

juce::AudioBuffer<float> pianoLine (double sr, double secs)
{
    juce::AudioBuffer<float> out (2, (int) (secs * sr)); out.clear();
    const double notes[] = { 261.63, 329.63, 392.0, 523.25, 493.88, 392.0, 329.63, 293.66, 261.63, 196.0, 220.0, 261.63 };
    const double step = secs / 12.0;
    for (int i = 0; i < 12; ++i)
    {
        auto t = tone (sr, juce::jmin (2.5, secs - i * step), { notes[i] }, 0.55, 2.2, true);
        const int o = (int) (i * step * sr);
        const int n = juce::jmin (t.getNumSamples(), out.getNumSamples() - o);
        out.addFrom (0, o, t, 0, 0, n, 0.5f); out.addFrom (1, o, t, 0, 0, n, 0.5f);
    }
    normalise (out, 0.8f);
    return out;
}
